import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as r}from"./app-COWo54fn.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S09/S09E18.html","title":"S09E18 The One with the Lottery","lang":"zh-CN","frontmatter":{"title":"S09E18 The One with the Lottery","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":212},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":33.74,"words":10122},"filePathRelative":"语言/英语/Friends老友记/S09/S09E18.md"}`),a={name:`S09E18.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-with-the-lottery" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-lottery"><span>The One with the Lottery</span></a></h1><blockquote><p><em>有彩票的那个</em></p></blockquote><p><strong>Teleplay:</strong> Sherry Bilsing - Graham &amp; Ellen Plummer</p><blockquote><p>雪莉·比尔辛-格雷厄姆和艾伦·普卢默</p></blockquote><p><strong>Story:</strong> Brian Buckner &amp; Sebastian Jones</p><blockquote><p>布莱恩·巴克纳和塞巴斯蒂安·琼斯</p></blockquote><p><strong>Directed by: Gary Halvorson</strong></p><blockquote><p>导演：加里·哈沃森</p></blockquote><p><strong>Transcribed by: Eleonora, Pheeboh, Roni &amp; Vanessa</strong></p><blockquote><p>转录人：Eleonora、Pheeboh、Roni&amp;Vanessa</p></blockquote><hr><p>🎬 <em>Central Perk - Chandler, Monica, Phoebe, Ross and Rachel are sitting on the sofas. Joey enters</em></p><blockquote><p>🎬 <em>中央公园-钱德勒、莫妮卡、菲比、罗斯和瑞秋坐在沙发上。乔伊进来</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Monica, hey, can I borrow the Porsche?</p><blockquote><p>莫妮卡，嘿，我能借用一下保时捷吗？</p></blockquote><p><strong>Monica Geller:</strong> Ok.</p><blockquote><p>好的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Alright!</p><blockquote><p>好吧！</p></blockquote><p><strong>Monica Geller:</strong> But ehm...what is it not?</p><blockquote><p>但嗯……那不是什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> (abashed) A place to entertain my lady friends.</p><blockquote><p>（羞愧地）一个娱乐我女朋友的地方。</p></blockquote><p><strong>Monica Geller:</strong> And what else is it not?</p><blockquote><p>还有什么不是？</p></blockquote><p><strong>Joey Tribbiani:</strong> (even more abashed) A place to eat spaghetti.</p><blockquote><p>（更加尴尬）吃意大利面的地方。</p></blockquote><p><strong>Monica Geller:</strong> Very good! (Gives him the keys) What do you need it for anyway?</p><blockquote><p>很好！（把钥匙给了他）你用它干什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh well, the powerball lottery is upto 300 million and they don&#39;t sell tickets here in New York, so...</p><blockquote><p>哦，好吧，强力球彩票高达3亿，而且在纽约这里不卖彩票，所以。。。</p></blockquote><p><strong>Rachel Green:</strong> Oh! So you&#39;re driving up to Connecticut?</p><blockquote><p>哦！你要开车去康涅狄格州？</p></blockquote><p><strong>Joey Tribbiani:</strong> (hesitates for a moment)Yeah Connecticut...Not West Virginia.</p><blockquote><p>（犹豫了一会儿）是的，康涅狄格州……不是西弗吉尼亚州。</p></blockquote><p><strong>Monica Geller:</strong> Hey, maybe I&#39;ll drive you up there! I&#39;d like to buy some tickets myself!</p><blockquote><p>嘿，也许我会开车送你上去！我想自己买几张票！</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh!</p><blockquote><p>嗯！</p></blockquote><p><strong>Monica Geller:</strong> Yeah with Chandler not getting paid, we could really use 300 million dollars.</p><blockquote><p>是的，钱德勒没有得到报酬，我们真的需要3亿美元。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, because if I was at my old job we&#39;d say 300 million? No thank you!</p><blockquote><p>是的，因为如果我是我以前的工作，我们会说3亿？不，谢谢！</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey will you get me tickets too?</p><blockquote><p>嘿，你也给我买票好吗？</p></blockquote><p><strong>Rachel Green:</strong> Yeah me too. oh! I have an idea. Why don&#39;t we all pitch in 50 bucks, we&#39;ll pool our money together and then if we win, we&#39;ll split it!</p><blockquote><p>是啊，我也是。哦我有个主意。我们为什么不一起投50美元，我们把钱凑在一起，如果我们赢了，我们就平分这笔钱！</p></blockquote><p>Everyone almost simultaneously except **Ross Geller: **yeah thats a great idea!</p><blockquote><p>每个人几乎同时都有，除了<strong>罗斯·盖勒：</strong>是的，这是个好主意！</p></blockquote><p><strong>Ross Geller:</strong> No thanks!</p><blockquote><p>不用了，谢谢！</p></blockquote><p><strong>Phoebe Buffay:</strong> You don&#39;t wanna win the lottery?</p><blockquote><p>你不想中彩票吗？</p></blockquote><p><strong>Ross Geller:</strong> (in a mocking voice)Uh...sure I do, and I also wanna be King of my own country and find out what happened to Amelia Earhart.</p><blockquote><p>（用嘲弄的声音）嗯……我当然想，我也想成为我自己国家的国王，看看阿米莉亚·埃尔哈特发生了什么事。</p></blockquote><p><strong>Chandler Bing:</strong> Still on Amelia Earhart?</p><blockquote><p>艾米莉亚·埃尔哈特还在吗？</p></blockquote><p><strong>Ross Geller:</strong> The woman just vanished!</p><blockquote><p>那个女人刚刚消失了！</p></blockquote><p><strong>Joey Tribbiani:</strong> Seriously, Ross, you don&#39;t want in on this?</p><blockquote><p>说真的，罗斯，你不想参与吗？</p></blockquote><p><strong>Ross Geller:</strong> No! Do you know what your odds are of winning the lottery? I...I mean you have a better chance of being struck by lightning 42 times.</p><blockquote><p>不！你知道你中彩票的几率是多少吗？我…我是说你被闪电击中42次的几率更大。</p></blockquote><p><strong>Chandler Bing:</strong> Yes but there&#39;s six of us so we&#39;d only have to get struck by lightning 7 times.</p><blockquote><p>是的，但是我们有六个人，所以我们只需要被闪电击中七次。</p></blockquote><p><strong>Joey Tribbiani:</strong> I like those odds!</p><blockquote><p>我喜欢那些机会！</p></blockquote><p><strong>Ross Geller:</strong> Seriously you guys, I can&#39;t believe you&#39;re going to spend 250 dollars on the lottery, I mean that&#39;s such a bunch of boohaki.</p><blockquote><p>说真的，你们这些家伙，我真不敢相信你们会花250美元买彩票，我的意思是这真是一堆博哈基。</p></blockquote><p><strong>Chandler Bing:</strong> (looking around at the others)I&#39;ll ask. (To Ross) Boohaki?</p><blockquote><p>（环顾四周）我会问的。（对罗斯）布哈基？</p></blockquote><p><strong>Ross Geller:</strong> Oh oh, we think Emma is about to start talking so we&#39;re trying to be careful about what words we use in front of her.</p><blockquote><p>哦，哦，我们认为艾玛就要开始说话了，所以我们要小心在她面前用什么词。</p></blockquote><p><strong>Rachel Green:</strong> Yeah so get ready to hear alot of ehm...boohaki, goshdarnit and brotherpucker.</p><blockquote><p>是的，所以准备好听很多的嗯…布哈基，戈什达尼特和兄弟泡妞。</p></blockquote><p><strong>Monica Geller:</strong> How do you know she&#39;s gonna start talking?</p><blockquote><p>你怎么知道她会开始说话？</p></blockquote><p><strong>Rachel Green:</strong> Well when I talk to her I almost feel like she understands what I&#39;m saying.</p><blockquote><p>当我和她说话的时候，我几乎觉得她明白我在说什么。</p></blockquote><p><strong>Chandler Bing:</strong> Kinda like Joey.</p><blockquote><p>有点像乔伊。</p></blockquote><p><strong>Joey Tribbiani:</strong> (who wasn&#39;t paying attention)What&#39;s that now?</p><blockquote><p>（谁没注意）那是什么？</p></blockquote><p>Opening credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s apartment. Monica, Chandler, Rachel and Joey are in the kitchen</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒的公寓。莫妮卡、钱德勒、瑞秋和乔伊在厨房</em></p></blockquote><p><strong>Monica Geller:</strong> God! Look at all these tickets! It&#39;s so exciting! You know I haven&#39;t won anything since the sixth grade.</p><blockquote><p>天哪！看这些票！太令人兴奋了！你知道我从六年级起就什么都没赢过。</p></blockquote><p><strong>Chandler Bing:</strong> Pie eating contest?</p><blockquote><p>吃馅饼比赛？</p></blockquote><p><strong>Monica Geller:</strong> Oh! You assume because I was heavy that&#39;s the only way I could win something?</p><blockquote><p>哦！你以为因为我很重这是我唯一能赢的方法？</p></blockquote><p><strong>Chandler Bing:</strong> No, I saw a picture of you covered in blueberries.</p><blockquote><p>不，我看到一张你满身蓝莓的照片。</p></blockquote><p><strong>Monica Geller:</strong> (smiling)That was a good day!</p><blockquote><p>（微笑）那是美好的一天！</p></blockquote><p><em>(Suddenly Ross comes running into the apartment)</em></p><blockquote><p><em>（罗斯突然跑进公寓）</em></p></blockquote><p><strong>Ross Geller:</strong> (yelling to Monica)They&#39;re towing your car, they&#39;re towing your car!!</p><blockquote><p>（对莫妮卡大叫）他们在拖你的车，他们在拖你的车！！</p></blockquote><p><strong>Monica Geller:</strong> I&#39;m parked in a garage on Morton!</p><blockquote><p>我把车停在莫顿的车库里！</p></blockquote><p><strong>Ross Geller:</strong> (panting)They&#39;re towing a car. And I am seeing...spots.</p><blockquote><p>（喘息）他们在拖一辆车。我看到…斑点。</p></blockquote><p><strong>Joey Tribbiani:</strong> (sounding panicky)Oh my god Ross! You don&#39;t have Emma! And Rachel you don&#39;t have Emma! (Starts yelling) Where&#39;s Emma? Who has Emma!?</p><blockquote><p>（听起来很惊慌）哦，我的天，罗斯！你没有艾玛！还有瑞秋，你没有艾玛！（开始大叫）艾玛在哪里？谁有爱玛！？</p></blockquote><p><strong>Rachel Green:</strong> Joey relax! My mother picked her up two hours ago. You were there!</p><blockquote><p>乔伊，放松！我妈妈两小时前接她的。你在那儿！</p></blockquote><p><strong>Joey Tribbiani:</strong> (not yelling anymore)I was?</p><blockquote><p>（不再喊叫）我是？</p></blockquote><p><strong>Racel:</strong> Yes and you talked to her...</p><blockquote><p>是的，你和她谈过。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> I did?</p><blockquote><p>是吗？</p></blockquote><p><strong>Rachel Green:</strong> She dropped off a casserole?</p><blockquote><p>她丢了一盘砂锅菜？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh yeah! The casserole lady.</p><blockquote><p>哦，是的！砂锅女工。</p></blockquote><p><strong>Monica Geller:</strong> (to Ross)So, did you come by to watch us win the big bucks?</p><blockquote><p>（对罗斯）那么，你是来看我们赢大钱的吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah, uh... and then I figured after you win, we could all go out to the balcony and see a night rainbow with gremlins dancing on top of it!</p><blockquote><p>是的，嗯。。。然后我想在你赢了之后，我们都可以到阳台上看夜虹，小精灵在上面跳舞！</p></blockquote><p><em>(phone starts ringing and Chandler comes running out of the bathroom)</em></p><blockquote><p><em>（电话开始响，钱德勒跑出浴室）</em></p></blockquote><p><strong>Chandler Bing:</strong> (hysterical)Don&#39;t touch the phone! I&#39;ll get it, I&#39;ll get it, I&#39;ll get it!! (picks up the phone)</p><blockquote><p>（歇斯底里地）别碰电话！我会的，我会的，我会的！！（拿起电话）</p></blockquote><p><strong>Ross Geller:</strong> (to Monica)Think he washed his hands?</p><blockquote><p>（对莫妮卡）你觉得他洗手了吗？</p></blockquote><p><strong>Chandler Bing:</strong> (into receiver)Hello? Hey Charlie, what do you know?</p><blockquote><p>（对着听筒）喂？嘿，查理，你知道什么？</p></blockquote><p><strong>Rachel Green:</strong> (to Monica)What&#39;s going on?</p><blockquote><p>（对莫妮卡）怎么了？</p></blockquote><p><strong>Monica Geller:</strong> Chandler is supposed to find out if he&#39;s getting an assistent job at his ad agency. But out of the 15 interns, they are only hiring three.</p><blockquote><p>钱德勒应该知道他是否在他的广告公司得到一份助理工作。但在15名实习生中，他们只雇佣了3名。</p></blockquote><p><strong>Joey Tribbiani:</strong> Ooh! Tough odds!</p><blockquote><p>哦！困难重重！</p></blockquote><p><strong>Ross Geller:</strong> (mockingly)Yeah if only it were a sure thing like your 24 state lottery!</p><blockquote><p>（嘲弄地）是啊，要是能像你的24州彩票那样有把握就好了！</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling)Look who&#39;s coming around!</p><blockquote><p>（微笑）看谁来了！</p></blockquote><p><strong>Chandler Bing:</strong> (still on the phone)Damnit. Alright call me when you know more.</p><blockquote><p>（还在打电话）该死。好吧，知道更多的时候给我打电话。</p></blockquote><p><strong>Joey Tribbiani:</strong> (excited)Did you get it?</p><blockquote><p>（兴奋）你明白了吗？</p></blockquote><p><strong>Chandler Bing:</strong> One of the slots got filled.</p><blockquote><p>其中一个位置被填满了。</p></blockquote><p><strong>Joey Tribbiani:</strong> (Still excited)By you!?</p><blockquote><p>（仍然兴奋）是你！？</p></blockquote><p><strong>Chandler Bing:</strong> Sense the tone! No that kid Nate got it.</p><blockquote><p>感觉一下语气！不，那个孩子，内特拿到了。</p></blockquote><p><strong>Monica Geller:</strong> Oh! I hate that guy! I mean come on kid! Pull up your pants!</p><blockquote><p>哦！我讨厌那个家伙！我是说来吧，孩子！拉起你的裤子！</p></blockquote><p><strong>Chandler Bing:</strong> Yeah I know.</p><blockquote><p>是的，我知道。</p></blockquote><p><strong>Rachel Green:</strong> Well, there&#39;s two spots left right?</p><blockquote><p>嗯，左边有两个点，右边有两个点？</p></blockquote><p><strong>Chandler Bing:</strong> Yeah...I mean I want this so much! I mean, I wanna get one, I want my friend Charlie to get one...Except I don&#39;t care about Charlie.</p><blockquote><p>是的……我是说我太想要这个了！我是说，我想要一个，我想要我的朋友查理得到一个…除了我不在乎查理。</p></blockquote><p><em>(Phoebe enters)</em></p><blockquote><p><em>（菲比进来）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (excited)Hey you guys! Ok, you&#39;re not going to believe this! I just saw my psychic and she said I was definitely gonna win the lottery tonight!</p><blockquote><p>（兴奋）嘿，你们！好吧，你不会相信的！我刚看到我的通灵师，她说我今晚一定会中彩票！</p></blockquote><p><strong>Monica Geller:</strong> Hey that reminds me, I thought we could use some extra luck so I brought a wishbone home from work.</p><blockquote><p>嘿，这提醒了我，我想我们需要一些额外的运气，所以我下班带了一个叉骨回家。</p></blockquote><p><strong>Ross Geller:</strong> (mockingly)A psychic AND a wishbone? Guys! Give someone else a chance!</p><blockquote><p>（嘲弄地）一个通灵师和一个许愿骨？伙计们！给别人一个机会！</p></blockquote><p><strong>Monica Geller:</strong> Alright, who wants to do it?</p><blockquote><p>好吧，谁想这么做？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh can I? Vegetarians never get to do the wishbone. It&#39;s really not fair either! You know, just because we don&#39;t eat the meat doesn&#39;t mean we don&#39;t like to play with the carcasses!</p><blockquote><p>哦，我可以吗？素食者永远不会做叉骨。这也真的不公平！你知道，我们不吃肉并不意味着我们不喜欢玩尸体！</p></blockquote><p><strong>Monica Geller:</strong> Ok, hey Rach?</p><blockquote><p>好的，嘿，瑞秋？</p></blockquote><p><strong>Rachel Green:</strong> Oh no, I&#39;m good, I don&#39;t wanna get that turkey smell all over my hands.</p><blockquote><p>哦，不，我很好，我不想让火鸡的味道弄得我手上到处都是。</p></blockquote><p><strong>Joey Tribbiani:</strong> I&#39;ll do it!! It&#39;ll get the casserole stink off of mine.</p><blockquote><p>我会的！！这会让我的砂锅味道消失。</p></blockquote><p><em>(Phoebe and Joey both grab one side of the wishbone)</em></p><blockquote><p><em>（菲比和乔伊都抓住了叉骨的一边）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> I hope I win!</p><blockquote><p>我希望我赢！</p></blockquote><p><strong>Monica Geller:</strong> Well, it doesn&#39;t really matter ... you&#39;re both wishing for the same thing, right?</p><blockquote><p>嗯，其实没关系。。。你们俩的愿望是一样的，对吧？</p></blockquote><p><strong>Joey Tribbiani:</strong> I can&#39;t tell you what I&#39;m wishing for! Else...you know...won&#39;t come true!</p><blockquote><p>我不能告诉你我想要什么！否则…你知道…就不会实现了！</p></blockquote><p><strong>Monica Geller:</strong> Right! .. but we &quot;know&quot; what you&#39;re wishing for!</p><blockquote><p>对。。但我们“知道”你想要什么！</p></blockquote><p><strong>Joey Tribbiani:</strong> Can&#39;t really say!</p><blockquote><p>真不敢说！</p></blockquote><p><strong>Monica Geller:</strong> I understand, but you&#39;re wishing for what we think you&#39;re wishing for, aren&#39;t you?</p><blockquote><p>我明白，但你希望得到我们认为你希望得到的东西，不是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> (slightly irritated)I&#39;m not really comfortable with these questions!</p><blockquote><p>（有点生气）我对这些问题不太满意！</p></blockquote><p>Rachel, Chandler and **Monica Geller: **Please, just do it!</p><blockquote><p>瑞秋、钱德勒和<strong>莫妮卡·盖勒：</strong>求你了，就这么做吧！</p></blockquote><p><strong>Phoebe Buffay:</strong> One, two, three!</p><blockquote><p>一，二，三！</p></blockquote><p><em>(they break the wishbone)</em></p><blockquote><p><em>（他们打破了叉骨）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> I won, hey!</p><blockquote><p>我赢了，嘿！</p></blockquote><p><strong>Ross Geller:</strong> You know what, I&#39;m sure your wish is gonna come true, but, you guys - just in case, maybe a genie will come out if we rub this lamp! (rubs lamp, stops because it&#39;s very hot) Ah!! That thing gets hot!!</p><blockquote><p>你们知道吗，我肯定你们的愿望会实现，但是，你们这些家伙——以防万一，如果我们擦这盏灯，也许会有一个妖怪出来！（擦灯，因为很热而停下来）啊！！那东西变热了！！</p></blockquote><p><strong>Rachel Green:</strong> You know, Ross, just keep making your jokes. How are you gonna feel if we actually do win?</p><blockquote><p>你知道，罗斯，继续开玩笑吧。如果我们真的赢了你会怎么想？</p></blockquote><p><strong>Ross Geller:</strong> Uh, you&#39;re not gonna win.</p><blockquote><p>嗯，你不会赢的。</p></blockquote><p><strong>Rachel Green:</strong> Oh, I know, I know, the odds are against us, but somebody has to win, and it could be us! And then how you gonna feel? You know, we&#39;re gonna be all like &quot;oh everybody, let&#39;s take our helicopters up to the cape&quot; and you&#39;re gonna be all like &quot;oh, I can&#39;t guys, I&#39;ll meet you guys up there, I gotta gas up the Hyundai&quot;</p><blockquote><p>哦，我知道，我知道，机会对我们不利，但总有人会赢，可能是我们！然后你会有什么感觉？你知道，我们都会说“哦，大家，让我们把直升机开到海角去吧”而你会说“哦，我不能，伙计们，我会在那里等你们，我要给现代加油”</p></blockquote><p><strong>Ross Geller:</strong> Ok, I&#39;ve heard myself on tape and I sound nothing like that.</p><blockquote><p>好吧，我在录音带上听到过我自己的声音，我听起来一点也不像。</p></blockquote><p><strong>Chandler Bing:</strong> I can see the headline now: &quot;Lottery winners&#39; friend filled with regret eats own arm&quot;.</p><blockquote><p>我现在可以看到标题了：“彩票中奖者的朋友后悔吃了自己的胳膊”。</p></blockquote><p><strong>Ross Geller:</strong> Why would I eat my own arm?</p><blockquote><p>我为什么要吃自己的胳膊？</p></blockquote><p><strong>Chandler Bing:</strong> Well you wouldn&#39;t, but we own the paper, we can print whatever we want.</p><blockquote><p>你不会的，但是我们拥有报纸，我们可以打印我们想要的任何东西。</p></blockquote><p><strong>Monica Geller:</strong> You know what, Ross? I&#39;m gonna throw in 50 bucks for you.</p><blockquote><p>你知道吗，罗斯？我会给你50美元。</p></blockquote><p><strong>Ross Geller:</strong> Why?</p><blockquote><p>为什么？</p></blockquote><p><strong>Monica Geller:</strong> Because I know that you think the lottery is &quot;boohaki&quot; but we&#39;re all here and gonna watch the numbers and have fun. And you&#39;re my brother, and I want you to be a part of this.</p><blockquote><p>因为我知道你认为彩票是“博哈基”，但我们都在这里，看数字，玩得开心。你是我的兄弟，我希望你能参与其中。</p></blockquote><p><strong>Ross Geller:</strong> You don&#39;t have to do that, I&#39;ll pay for myself. But just the fact that you want me to have fun with you guys - that&#39;s so sweet! Come here (they kiss and hug)</p><blockquote><p>你不必那么做，我自己付。但事实上，你想让我和你们玩得开心，真是太好了！过来（他们亲吻拥抱）</p></blockquote><p><strong>Phoebe Buffay:</strong> Get a room!</p><blockquote><p>找个房间！</p></blockquote><p><strong>Chandler Bing:</strong> Ok, so now that you&#39;re in, what are you gonna do if we win?</p><blockquote><p>好吧，既然你加入了，如果我们赢了，你打算怎么办？</p></blockquote><p><strong>Ross Geller:</strong> I don&#39;t know, probably just invest it.</p><blockquote><p>我不知道，可能只是投资而已。</p></blockquote><p><strong>Chandler Bing:</strong> Ooh! Calm down ...</p><blockquote><p>哦！冷静</p></blockquote><p><strong>Joey Tribbiani:</strong> Seriously, that&#39;s your fantasy? To invest it?</p><blockquote><p>说真的，那是你的幻想？投资？</p></blockquote><p><strong>Ross Geller:</strong> Oh, I&#39;m sorry, did I say &quot;invest it&quot;? I meant &quot;be cool and piss it all away&quot; (Joey and Chandler pleased)</p><blockquote><p>哦，对不起，我是说“投资”吗？我的意思是“冷静一点，把它全尿掉”（乔伊和钱德勒很高兴）</p></blockquote><p><strong>Joey Tribbiani:</strong> Ooh, ooh, I know! We should pool all own money and buy the Knicks!</p><blockquote><p>哦，哦，我知道！我们应该把所有的钱都集中起来买尼克斯队！</p></blockquote><p><strong>Rachel Green:</strong> I don&#39;t really care about the Knicks.</p><blockquote><p>我真的不在乎尼克斯队。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, you will when I pick you as starting forward.</p><blockquote><p>哦，当我选你为首发前锋时，你会的。</p></blockquote><p><strong>Rachel Green:</strong> (touched) You would do that? I never get picked!</p><blockquote><p>（感动）你会这么做吗？我从来没有被选中过！</p></blockquote><p><strong>Chandler Bing:</strong> You know, I&#39;m not sure a sports team is the way to go.</p><blockquote><p>你知道，我不确定一支运动队是不是该走的路。</p></blockquote><p><strong>Joey Tribbiani:</strong> You&#39;re not gonna let me buy the Knicks?? I can&#39;t believe you&#39;re taking this away from me!</p><blockquote><p>你不会让我买尼克斯队吧？？我不敢相信你把这个从我身上拿走了！</p></blockquote><p><strong>Chandler Bing:</strong> You&#39;re right, it has been you dream for over 15 seconds.</p><blockquote><p>你说得对，这是你15秒多以来的梦想。</p></blockquote><p><strong>Ross Geller:</strong> (to Rachel) Uh, how long until they announce the numbers, Mommy?</p><blockquote><p>（对瑞秋）嗯，还要多久他们才会公布数字，妈妈？</p></blockquote><p><em>(pause)</em></p><blockquote><p><em>（停顿）</em></p></blockquote><p><strong>Chandler Bing:</strong> (looks around) I&#39;ll take this one too (to Ross) Uh ... Mommy?</p><blockquote><p>（环顾四周）我也要这个（给罗斯）嗯。。。妈妈？</p></blockquote><p><strong>Ross Geller:</strong> Oh, I&#39;ve gotten into the habit of calling Rachel &quot;Mommy&quot; when we&#39;re around Emma. Which I now realize we are not ...</p><blockquote><p>噢，当我们在艾玛身边时，我已经养成了叫瑞秋“妈妈”的习惯。我现在意识到我们不是。。。</p></blockquote><p><strong>Rachel Green:</strong> I&#39;m hoping that if she hears it enough it will be her first word.</p><blockquote><p>我希望如果她听够了，这将是她的第一句话。</p></blockquote><p><strong>Ross Geller:</strong> Although if we&#39;re gonna do that, we should probably call me &quot;Daddy&quot; too.</p><blockquote><p>不过如果我们要这么做，我们可能也应该叫我“爸爸”。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oooh, I like that, &quot;daddy&quot; (in a sexy tone)</p><blockquote><p>哦，我喜欢“爸爸”（用性感的语气）</p></blockquote><p><strong>Ross Geller:</strong> I ... I was just talking about Rachel.</p><blockquote><p>我。。。我刚才说的是瑞秋。</p></blockquote><p><strong>Phoebe Buffay:</strong> (still in sexy tone) Oooh, is daddy getting angry? Is daddy gonna spank me?</p><blockquote><p>（仍然用性感的语气）哦，爸爸生气了吗？爸爸会打我屁股吗？</p></blockquote><p><strong>Ross Geller:</strong> (tries to be sexy too) Well that depends ... have you been a baaad gi .. (stops) no I can&#39;t.</p><blockquote><p>（也试着性感）那要看情况了。。。你是巴亚德的士兵吗。。（停下来）不，我不能。</p></blockquote><p><em>(Phone rings, Chandler picks up)</em></p><blockquote><p><em>（电话铃响了，钱德勒接电话）</em></p></blockquote><p><strong>Chandler Bing:</strong> Hello? Hello? Oh, hey Charlie. Did anybody else hear? ... What? Susan got it?? How? Oh man, I would have slept with him!! .. Alright, bye. (hangs up)</p><blockquote><p>喂？你好哦，嘿，查理。还有人听到吗。。。什么？苏珊明白了吗？？怎么用？哦，天哪，我会和他上床的。。好的，再见。（挂断电话）</p></blockquote><p><strong>Joey Tribbiani:</strong> Dude, I&#39;m sorry. But hey, there&#39;s one spot left, right?</p><blockquote><p>伙计，对不起。但是，嘿，还有一个位置，对吗？</p></blockquote><p><strong>Chandler Bing:</strong> Well no, Charlie&#39;s gonna get that.</p><blockquote><p>不，查理会明白的。</p></blockquote><p><strong>Monica Geller:</strong> Hey, don&#39;t say that! You got just as good a chance as anybody else of getting that job!</p><blockquote><p>嘿，别这么说！你和其他人一样有机会得到那份工作！</p></blockquote><p><strong>Chandler Bing:</strong> He&#39;s the boss&#39;s son.</p><blockquote><p>他是老板的儿子。</p></blockquote><p><strong>Monica Geller:</strong> Come on, lottery!! (everybody cheers)</p><blockquote><p>来吧，彩票！！（大家欢呼）</p></blockquote><p><strong>Rachel Green:</strong> Ooh, you guys, it starts in like 20 minutes.</p><blockquote><p>哦，伙计们，大概20分钟后开始。</p></blockquote><p><strong>Monica Geller:</strong> Ok, here we go. We need to sort out the tickets as quickly as possible to see if we&#39;ve won. So does anybody have any ideas how to organize this? (doesn&#39;t let them answer) Ok, how about this: we divide them into 6 groups of 40, and the remaining 10 can be read by whoever finishes their pile first.</p><blockquote><p>好的，开始吧。我们需要尽快把票整理好，看看我们是否赢了。那么，有没有人知道如何组织这一切？（不让他们回答）好的，这个怎么样：我们把他们分成6组，每组40人，剩下的10人可以由谁先完成他们的一堆来阅读。</p></blockquote><p><strong>Rachel Green:</strong> Ooh, I have another idea!</p><blockquote><p>哦，我有另一个主意！</p></blockquote><p><strong>Monica Geller:</strong> I&#39;m sorry, idea time is over.</p><blockquote><p>对不起，创意时间到了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ok, well, are all the tickets in the bowl?</p><blockquote><p>好吧，那么，所有的票都在碗里吗？</p></blockquote><p><strong>Monica Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Chandler Bing:</strong> What about the ones you have on the nightstand?</p><blockquote><p>那你床头柜上的那些呢？</p></blockquote><p><strong>Monica Geller:</strong> There are no tickets on the nightstand!</p><blockquote><p>床头柜上没有票！</p></blockquote><p><strong>Chandler Bing:</strong> Yes there are, I just saw them a few minutes ago.</p><blockquote><p>是的，我几分钟前刚看到他们。</p></blockquote><p><em>(Rachel get suspicious)</em></p><blockquote><p><em>（瑞秋开始怀疑）</em></p></blockquote><p><strong>Monica Geller:</strong> Un, no you didn&#39;t! You must be mistaken!</p><blockquote><p>不，你没有！你一定弄错了！</p></blockquote><p><strong>Chandler Bing:</strong> Honey, there are like 20 tickets on the nightstand!</p><blockquote><p>亲爱的，床头柜上大概有20张票！</p></blockquote><p><strong>Monica Geller:</strong> Chandler, sense the tone!!</p><blockquote><p>钱德勒，感受一下语气！！</p></blockquote><p><em>(Rachel comes out of their bedroom waving tickets)</em></p><blockquote><p><em>（瑞秋从卧室里出来挥舞着票）</em></p></blockquote><p><strong>Rachel Green:</strong> Well, well, well, look what mommy found!!</p><blockquote><p>好吧，好吧，好吧，看看妈妈发现了什么！！</p></blockquote><p><em>(everyone&#39;s shocked)</em></p><blockquote><p><em>（大家都很震惊）</em></p></blockquote><p><strong>Monica Geller:</strong> Ok, fine!! I bought 20 extra tickets for me and Chandler.</p><blockquote><p>好的，很好！！我为我和钱德勒多买了20张票。</p></blockquote><p><strong>Phoebe Buffay:</strong> Uh! The psychic also said that I would be betrayed.</p><blockquote><p>嗯！巫师还说我会被背叛。</p></blockquote><p><strong>Ross Geller:</strong> I can&#39;t believe this, I thought we were all in this together!</p><blockquote><p>我真不敢相信，我还以为我们都在一起呢！</p></blockquote><p><strong>Monica Geller:</strong> Hey, you just got in 5 minutes ago!</p><blockquote><p>嘿，你5分钟前才进来！</p></blockquote><p><strong>Ross Geller:</strong> 3 minutes ago!!! I don&#39;t know why that&#39;s important ...</p><blockquote><p>三分钟前！！！我不知道为什么这很重要。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> I was with you the whole time we were in Connecticut, when did you even get those?</p><blockquote><p>我们在康涅狄格州的时候我一直和你在一起，你什么时候拿到的？</p></blockquote><p><strong>Monica Geller:</strong> When you were reading the dirty magazines without taking off the plastic!</p><blockquote><p>当你在看脏杂志的时候，却没有把塑料脱下来！</p></blockquote><p><strong>Joey Tribbiani:</strong> (to Ross) I&#39;ll show you how.</p><blockquote><p>（对罗斯）我来教你怎么做。</p></blockquote><p><strong>Rachel Green:</strong> Ok, well Monica, suppose one of your &quot;special&quot; tickets win? How are you gonna feel when you win the lottery and you lose all your friends?</p><blockquote><p>好吧，莫妮卡，假设你的一张“特别”票赢了？当你中了彩票，失去了所有的朋友，你会有什么感觉？</p></blockquote><p><strong>Monica Geller:</strong> Please ... if I win the lottery, you guys are not gonna leave me. Someone gave me a basket of mini-muffins last week and I couldn&#39;t get rid of you for 3 days!</p><blockquote><p>请。。。如果我中了彩票，你们不会离开我的。上周有人给了我一篮迷你松饼，我有三天没能摆脱你！</p></blockquote><p><strong>Rachel Green:</strong> Chandler, would you just tell her what she did was wrong?</p><blockquote><p>钱德勒，你能告诉她她做错了什么吗？</p></blockquote><p><strong>Chandler Bing:</strong> (to Mon) She&#39;s right, you shouldn&#39;t have bought tickets just for us ...</p><blockquote><p>她是对的，你不应该只为我们买票。。。</p></blockquote><p><strong>Monica Geller:</strong> Ahhh! (shocked)</p><blockquote><p>啊！（震惊）</p></blockquote><p><strong>Chandler Bing:</strong> Let me finish ... (to everyone else) however, it doesn&#39;t look like I&#39;m gonna get this job so I can&#39;t afford to have principles, so screw you, the tickets are ours!! (takes tickets from Rachel)</p><blockquote><p>让我说完。。。（对其他人）然而，看起来我不会得到这份工作，所以我不能有原则，所以去你的，票是我们的！！（从瑞秋那里取票）</p></blockquote><p><strong>Monica Geller:</strong> There&#39;s the man I married!!</p><blockquote><p>这就是我娶的那个男人！！</p></blockquote><p><strong>Rachel Green:</strong> All right, believe me.If you win the lottery, it&#39;s the last you&#39;re gonna hear from us!</p><blockquote><p>好吧，相信我。如果你中了彩票，这是你最后一次听到我们的消息！</p></blockquote><p><strong>Monica Geller:</strong> Fine! Don&#39;t be my friends! I&#39;ll buy new friends! Yeah, and then I&#39;ll pay for their plastic surgery so they&#39;d look just like you!</p><blockquote><p>很好！不要做我的朋友！我要买新朋友！是的，然后我会付钱给他们做整形手术，让他们看起来和你一样！</p></blockquote><p><strong>Rachel Green:</strong> (surprised) OH! Alright, you know what? That&#39;s it! I want my share of the tickets (picks up the bowl)!</p><blockquote><p>（惊讶）哦！好吧，你知道吗？就这样！我要我那份票（拿起碗）！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, I want my tickets too (takes the bowl from Rachel)! And I&#39;m buying the Knicks! And Steffi Graff, ah ah!</p><blockquote><p>是的，我也想要我的票（从瑞秋那里拿碗）！我要买尼克斯队！还有Steffi Graff，啊啊！</p></blockquote><p><strong>Ross Geller:</strong> Than I want mine, too (takes the bowl from Joey)! And if I win I&#39;m gonna put it all into a very low-yield bond.</p><blockquote><p>我也想要我的（从乔伊那里拿碗）！如果我赢了，我会把所有的钱都投到一个低收益债券里。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, you guys! We&#39;ve got to keep all the tickets together (takes the bowl from Ross and puts it on the table)</p><blockquote><p>哦，你们这些家伙！我们必须把所有的票放在一起（从罗斯手中接过碗，放在桌子上）</p></blockquote><p><strong>Monica Geller:</strong> No, no! We should divide them up (picks up the bowl) and I should get extra because we used my card to buy them!</p><blockquote><p>不，不！我们应该把它们分开（拿起碗），我应该得到额外的钱，因为我们用我的卡买了它们！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, if anybody gets extra tickets, it should be me! This all thing was my idea! (takes the bowl from Monica)</p><blockquote><p>嘿，如果有人得到额外的票，应该是我！这一切都是我的主意！（从莫妮卡手中接过碗）</p></blockquote><p><strong>Chandler Bing:</strong> Oh, yeah! Thanks for inventing the lottery!</p><blockquote><p>哦，是的！谢谢你发明了彩票！</p></blockquote><p><strong>Rachel Green:</strong> Ok, that&#39;s it! Just give&#39;em to me! I&#39;ll split them up! (she tries to snatch the bowl from Joey&#39;s hands but she can&#39;t, so she pinches his nipple and she manages to take it)</p><blockquote><p>好的，就这样！把它们给我！我要把他们分开！（她试图从乔伊手中抢走碗，但她做不到，于是她捏了捏他的乳头，设法把它拿了下来）</p></blockquote><p><strong>Joey Tribbiani:</strong> (in pain) Oh!</p><blockquote><p>（痛苦地）哦！</p></blockquote><p><strong>Phoebe Buffay:</strong> (she takes the bowl from Rachel&#39;s hands and she starts running around the room and yelling) OOOOOHHHHH!</p><blockquote><p>（她从瑞秋手中接过碗，开始在房间里跑来跑去，大声喊道）噢！</p></blockquote><p><strong>Ross Geller:</strong> (trying to stop her) Hey, hey!!</p><blockquote><p>（试图阻止她）嘿，嘿！！</p></blockquote><p><strong>Phoebe Buffay:</strong> (keeping on running and yelling) OOOOOHHHHH! (she stops) Fine, I can&#39;t take it anymore! I&#39;m putting an end to this! (she goes out to the balcony)</p><blockquote><p>（不停地跑，不停地喊）哦哦！（她停下来）好吧，我再也受不了了！我要结束这一切！（她走到阳台上）</p></blockquote><p><strong>Rachel Green:</strong> Oh, if she jumps, I get her tickets.</p><blockquote><p>噢，如果她跳了，我就给她买票。</p></blockquote><p><strong>Joey Tribbiani:</strong> No, no! (they all go towards the balcony but they get jammed in the window)</p><blockquote><p>不，不！（他们都走向阳台，但被窗户卡住了）</p></blockquote><p><strong>Phoebe Buffay:</strong> If we are not doing it together, we&#39;re not doing it at all! So, say goodbye to your tickets! (She holds out the bowl, and makes as to drop the tickets on the street).</p><blockquote><p>如果我们不一起做，我们根本就不做！所以，跟你的票说再见吧！（她伸出碗，使劲把票扔到街上）。</p></blockquote><p><strong>Everyone:</strong> NO!!</p><blockquote><p>不！！</p></blockquote><p><strong>Phoebe Buffay:</strong> Don&#39;t come any closer!</p><blockquote><p>别再靠近了！</p></blockquote><p><strong>Chandler Bing:</strong> Can I come a little bit closer, valuable things are getting squished...</p><blockquote><p>我能靠近一点吗，贵重的东西都被压扁了。。。</p></blockquote><p><strong>Phoebe Buffay:</strong> No, what&#39;s more important, your friends or money?</p><blockquote><p>不，什么更重要，你的朋友还是钱？</p></blockquote><p>Everyone but **Monica Geller: **Friends!</p><blockquote><p>除了莫妮卡，所有人都是朋友！</p></blockquote><p><strong>Monica Geller:</strong> Money! (they all look at her) Friends...</p><blockquote><p>钱！（他们都看着她）朋友们。。。</p></blockquote><p><strong>Phoebe Buffay:</strong> Hey Monica, what about your extra tickets?</p><blockquote><p>嘿，莫妮卡，你额外的票呢？</p></blockquote><p><strong>Monica Geller:</strong> They&#39;re all in there! Even these five that I hid in my bra (takes some tickets out of her bra and gives them to Phoebe)...</p><blockquote><p>他们都在里面！甚至我藏在胸罩里的这五张票（从她的胸罩里拿出一些票给菲比）。。。</p></blockquote><p><strong>Ross Geller:</strong> Monica!</p><blockquote><p>莫妮卡！</p></blockquote><p><strong>Phoebe Buffay:</strong> Ok, good! (pause) You guys were so scared! There was no way I was gonna dump this...(a pigeon swoops down, scaring Phoebe who drops the bowl on the street) Oh God, no! (pause) I think I broke your bowl.</p><blockquote><p>好的，很好！（停顿）你们太害怕了！我不可能扔掉这个…（一只鸽子猛扑下来，吓坏了把碗掉在街上的菲比）哦，天哪，不！（停顿）我想我打碎了你的碗。</p></blockquote><p><strong>Ross Geller:</strong> Go, go, go!!</p><blockquote><p>走，走，走！！</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s apartment.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒的公寓</em></p></blockquote><p><em>(All are returning from the street after picking up dropped lottery tickets)</em></p><blockquote><p><em>（所有人都在捡到丢失的彩票后从街上回来）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> What a beautiful night to be running around the street, looking for tickets. And the wind sure made it fun.</p><blockquote><p>这是一个多么美好的夜晚啊，在街上跑来跑去，寻找车票。风确实让它很有趣。</p></blockquote><p><strong>Monica Geller:</strong> Phoebe, we lost half of them.</p><blockquote><p>菲比，我们失去了一半。</p></blockquote><p><strong>Phoebe Buffay:</strong> So, what? Monica, we have the winning ticket! My psychic said I was gonna win, remember?</p><blockquote><p>那又怎么样？莫妮卡，我们赢了！我的通灵师说我会赢，记得吗？</p></blockquote><p><strong>Ross Geller:</strong> Weird.. your psychic didn&#39;t mention anything about the scary pigeon...</p><blockquote><p>奇怪。。你的通灵师没有提到任何关于那只吓人的鸽子的事。。。</p></blockquote><p><strong>Phoebe Buffay:</strong> As a matter of fact she said that&#39;s how I am going to die. (pause ) So, excuse me for being a little skittish.</p><blockquote><p>事实上，她说我就是这样死的。（停顿）所以，请原谅我有点神经质。</p></blockquote><p><strong>Chandler Bing:</strong> (looking at the answering machine) Hey, there&#39;s two messages. These could be from work!</p><blockquote><p>（看着电话答录机）嘿，有两条留言。这些可能是工作造成的！</p></blockquote><p><strong>Monica Geller:</strong> Oh, play them!</p><blockquote><p>哦，玩吧！</p></blockquote><p><strong>Chandler Bing:</strong> Ok, here we go! (he pushes the play button)</p><blockquote><p>好了，开始吧！（他按下播放按钮）</p></blockquote><p><strong>Message:</strong> (Phoebe&#39;s voice) &quot;Hello. Th-this is the pigeon from the balcony calling to apologise&quot; (they all turns to look at Phoebe) &quot;I sh.. I shouldn&#39;t have knocked the tickets out of the pretty lady&#39;s hand. It-it was all my fault. Not hers. Bye. Coo.&quot;</p><blockquote><p>（菲比的声音）“你好。这是阳台上的鸽子在打电话道歉”（他们都转过身来看着菲比）“我嘘……我不该把票从这位漂亮女士手里碰掉。都是我的错。不是她的。再见。Coo。”</p></blockquote><p><em>(they all keep staring at Phoebe)</em></p><blockquote><p><em>（他们都一直盯着菲比看）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Well, I bet that was very hard for him to do.</p><blockquote><p>嗯，我打赌这对他来说很难做到。</p></blockquote><p><strong>Second message:</strong> &quot;Hey Chandler, it&#39;s Charlie&quot;</p><blockquote><p>“嘿，钱德勒，我是查理”</p></blockquote><p><strong>Chandler Bing:</strong> This is..shhh!</p><blockquote><p>这是……嘘！</p></blockquote><p><strong>Second Message:</strong> &quot;Listen, oh... it turns I got the last spot. I&#39;m really sorry man, it was a lot of fun working with you. Give me a call if you want.&quot;</p><blockquote><p>“听着，哦……轮到我最后一个位置了。我真的很抱歉，伙计，和你一起工作很有趣。如果你愿意，给我打个电话。”</p></blockquote><p><strong>Monica Geller:</strong> Oh God, I am so sorry honey...</p><blockquote><p>哦，上帝，我很抱歉，亲爱的。。。</p></blockquote><p><strong>All:</strong> Oh, so sorry man! Sorry!</p><blockquote><p>哦，真对不起，伙计！很抱歉</p></blockquote><p><strong>Rachel Green:</strong> Oh, it is so unfair. It&#39;s like that time they promoted Sandra over me at work.</p><blockquote><p>哦，这太不公平了。就好像那一次他们在工作中提拔桑德拉胜过我一样。</p></blockquote><p><strong>Chandler Bing:</strong> Oh, is she related to Ralph Lauren?</p><blockquote><p>哦，她和拉尔夫·劳伦有亲戚关系吗？</p></blockquote><p><strong>Rachel Green:</strong> No, she was just much better at job than me!</p><blockquote><p>不，她只是在工作上比我强多了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Guys, the drawing is about to start!</p><blockquote><p>伙计们，绘画就要开始了！</p></blockquote><p><strong>Rachel Green:</strong> (To Ross) You know what? We should call my mum&#39;s house and say goodnight to Emma before she goes down.</p><blockquote><p>（对罗斯）你知道吗？我们应该在爱玛下楼之前给她打个电话，向她道晚安。</p></blockquote><p><strong>Ross Geller:</strong> Oh yeah, it&#39;s a good idea!</p><blockquote><p>哦，是的，这是个好主意！</p></blockquote><p><strong>Monica Geller:</strong> (she hugs Chandler) Honey, you&#39;ve been really strong about this, I know how badly you wanted that job.</p><blockquote><p>（她拥抱钱德勒）亲爱的，你在这件事上真的很坚强，我知道你多么渴望那份工作。</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, you know, I really thought I deserved it. (pause) But... let&#39;s go win the lottery... I mean, we still have 130 chances to win, right?</p><blockquote><p>是的，你知道，我真的认为这是我应得的。（停顿）但是。。。我们去中彩票吧。。。我是说，我们还有130次获胜的机会，对吗？</p></blockquote><p><strong>Monica Geller:</strong> (she draws out a ticket from a pocket of her pants) 131! (they kiss)</p><blockquote><p>（她从裤子口袋里掏出一张票）131！（他们接吻）</p></blockquote><p><strong>Ross Geller:</strong> (on the phone) Goodnight sweetheart! I love you. And remember, you&#39;re daddy&#39;s little girl... (covering the phone, to Rachel) Phoebe&#39;s totally ruined that for me... (he passes the receiver to Rachel)</p><blockquote><p>（在电话里）晚安，甜心！我爱你。记住，你是爸爸的小女儿。。。（盖住电话，对瑞秋）菲比完全毁了我的一切。。。（他把听筒递给瑞秋）</p></blockquote><p><strong>Rachel Green:</strong> Hi mum, put her back on!</p><blockquote><p>嗨，妈妈，把她放回去！</p></blockquote><p><strong>Joey Tribbiani:</strong> (sitting on the sofa in front of the tv) Rach, come on! They are announcing the numbers! My God, I can already feel myself changing.</p><blockquote><p>（坐在电视机前的沙发上）瑞秋，快点！他们正在公布数字！天哪，我已经感觉到自己在改变。</p></blockquote><p><strong>TV:</strong> &quot;Here we are, the official Powerball numbers! We have 53&quot;</p><blockquote><p>“我们到了，官方的强力球号码！我们有53个”</p></blockquote><p><strong>Chandler Bing:</strong> I got that!</p><blockquote><p>我明白了！</p></blockquote><p><strong>Ross Geller:</strong> Oh, we have one too!!</p><blockquote><p>哦，我们也有一个！！</p></blockquote><p><strong>Monica Geller:</strong> We are on a roll, people!!</p><blockquote><p>大家好，我们很顺利！！</p></blockquote><p><strong>Ross Geller:</strong> (calling Rachel) Come on!!</p><blockquote><p>（打电话给瑞秋）快点！！</p></blockquote><p><strong>Rachel Green:</strong> (on the phone) Mum, please!I know you love your new lips, but I can barely understand you! Would you, please, just let me say goodnight to my daughter?</p><blockquote><p>（在电话里）妈妈，求你了！我知道你喜欢你的新嘴唇，但我几乎无法理解你！请让我跟我女儿道晚安好吗？</p></blockquote><p><strong>TV:</strong> &quot;And number 29! Here we go! The Powerball is 7&quot;</p><blockquote><p>“还有29号！我们开始了！强力球是7号”</p></blockquote><p><strong>Monica Geller:</strong> Check your numbers! Make me rich!</p><blockquote><p>检查你的号码！让我发财！</p></blockquote><p><strong>Rachel Green:</strong> (she goes towards the others and she&#39;s very excited) Guys, you&#39;re not gonna believe this! I was just saying goodnight to Emma and she said her first words!!</p><blockquote><p>（她走向其他人，她非常兴奋）伙计们，你们不会相信的！我刚跟艾玛道晚安，她说了她的第一句话！！</p></blockquote><p><strong>All:</strong> Wow!</p><blockquote><p>哇！</p></blockquote><p><strong>Joey Tribbiani:</strong> And what did she say?</p><blockquote><p>她说了什么？</p></blockquote><p><strong>Rachel Green:</strong> She said &quot;gleba&quot;!! (she celebrates)</p><blockquote><p>她说“格莱巴”！！（她庆祝）</p></blockquote><p><em>(they just look at her for a moment; then they go back to checking the tickets)</em></p><blockquote><p><em>（他们只是看了她一会儿，然后又回去检查车票）</em></p></blockquote><p><strong>Monica Geller:</strong> Make me rich!!</p><blockquote><p>让我发财！！</p></blockquote><p><strong>Rachel Green:</strong> (to Ross) Isn&#39;t that amazing?</p><blockquote><p>（对罗斯）这不是很神奇吗？</p></blockquote><p><strong>Ross Geller:</strong> Oh yeah, no no no...that&#39;s great!</p><blockquote><p>哦，是的，不，不，不……太好了！</p></blockquote><p><strong>Rachel Green:</strong> Why-why aren&#39;t you more excited?</p><blockquote><p>你为什么不更兴奋？</p></blockquote><p><strong>Ross Geller:</strong> Oh, Rach...oh...&quot;gleba&quot; is not a word.</p><blockquote><p>哦，瑞秋……哦……“格莱巴”不是一个词。</p></blockquote><p><strong>Rachel Green:</strong> Oh, but of course it is!</p><blockquote><p>哦，当然是了！</p></blockquote><p><strong>Ross Geller:</strong> Okay, what does it mean?</p><blockquote><p>好吧，这是什么意思？</p></blockquote><p><strong>Rachel Green:</strong> I don&#39;t know all the words.</p><blockquote><p>我不知道所有的单词。</p></blockquote><p><strong>Ross Geller:</strong> I&#39;m just, I&#39;m just glad I didn&#39;t miss my daughter&#39;s first words (goes back to checking the tickets).</p><blockquote><p>我只是，我只是很高兴我没有错过我女儿的第一句话（回到查票）。</p></blockquote><p><strong>Ross Geller:</strong> Yes you did, gleba is a word!</p><blockquote><p>是的，你说了，格莱巴是个词！</p></blockquote><p><strong>Ross Geller:</strong> Ok, use it in a sentence.</p><blockquote><p>好的，用在句子里。</p></blockquote><p><strong>Rachel Green:</strong> Ok... &quot;Emma just said gleba&quot;!</p><blockquote><p>好的。。。“艾玛刚刚说了格雷巴”！</p></blockquote><p><strong>Ross Geller:</strong> It&#39;s not a word!</p><blockquote><p>这不是一个字！</p></blockquote><p><strong>Rachel Green:</strong> Okay, okay, okay, fine, I&#39;m gonna look it up (she goes and picks up the dictionary).</p><blockquote><p>好吧，好吧，好吧，好吧，我去查一下（她去拿字典）。</p></blockquote><p><strong>Ross Geller:</strong> Oh, oh, ok, great. You know what, while you&#39;re at it she said another word the other day, why don&#39;t you, why don&#39;t you look up: pbbqqt....</p><blockquote><p>哦，哦，好的，太好了。你知道吗，当你这么做的时候，前几天她又说了一句话，为什么你不，为什么你不抬头看看：PBBqt。。。。</p></blockquote><p><em>(Rachel glares at him)</em></p><blockquote><p><em>（瑞秋瞪着他）</em></p></blockquote><p><strong>Rachel Green:</strong> (searching the dictionary) Alright, okay, okay, gleba, gleba... (excited) Gleba! Ha! Here it is: the fleshy, spore-bearing inner mass of a certain fungi.</p><blockquote><p>（翻字典）好吧，好吧，好吧，格莱巴，格莱巴。。。（兴奋）格莱巴！哈这是：某种真菌的肉质、带孢子的内部物质。</p></blockquote><p><em>(Rachel shows Ross the definition on the dictionary, giving him a smug look; then she squints at the dictionary, as though unsure what to make out of it)</em></p><blockquote><p><em>（瑞秋给罗斯看字典上的定义，得意地看了他一眼；然后她眯着眼睛看字典，好像不知道该从字典里读什么）</em></p></blockquote><p><strong>Ross Geller:</strong> She&#39;s gonna be a scientist! (kisses Rachel on the head, very moved)</p><blockquote><p>她会成为一名科学家！（亲吻瑞秋的头，非常感动）</p></blockquote><p><strong>Joey Tribbiani:</strong> (checking the last ticket) Damnit! anybody got anything?</p><blockquote><p>（检查最后一张票）该死！有人有什么发现吗？</p></blockquote><p><strong>Chandler Bing:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Phoebe Buffay:</strong> I&#39;m still looking through mine...</p><blockquote><p>我还在看我的。。。</p></blockquote><p><strong>Monica Geller:</strong> Just double checking (does so)...no, no, no...(takes off a shoe and takes a ticket out of it) No!</p><blockquote><p>只是再检查一下（这样做）…不，不，不…（脱下鞋子，拿出一张票）不！</p></blockquote><p><em>(phone rings)</em></p><blockquote><p><em>（电话铃响）</em></p></blockquote><p><strong>Monica Geller:</strong> (answering phone) Hello? Hold on. It&#39;s your boss.</p><blockquote><p>（接电话）喂？等等是你的老板。</p></blockquote><p><strong>Chandler Bing:</strong> Ah, the &quot;I&#39;m sorry I rejected you&quot; phone call. I&#39;m not used to getting it from guys. (on the phone, getting up from the sofa) Hey, Steve.</p><blockquote><p>啊，“对不起，我拒绝了你”的电话。我不习惯从男人那里得到它。（在电话里，从沙发上站起来）嘿，史蒂夫。</p></blockquote><p><strong>Steve:</strong> Chandler, hi! I&#39;m sure you&#39;ve heard we filled the three positions. We just felt that with your maturity and experience, you wouldn&#39;t be happy being someone&#39;s assistant.</p><blockquote><p>钱德勒，你好！我相信你已经听说我们填补了这三个职位。我们只是觉得，以你的成熟和经验，你不会很高兴成为别人的助手。</p></blockquote><p><strong>Chandler Bing:</strong> Oh no no no no, I&#39;d love to be somebody&#39;s assistant! Answering phones, getting coffee, I live for that stuff! And I&#39;m not too mature... farts, boobies, butt cracks!</p><blockquote><p>哦，不，不，我很想成为别人的助手！接电话，喝咖啡，我就是为了这些！我还不太成熟。。。屁，胸，屁股裂！</p></blockquote><p><strong>Steve:</strong> Chandler, you were the strongest person in the program. We&#39;re offering you the position of junior copywriter.</p><blockquote><p>钱德勒，你是节目里最强壮的人。我们给你一个初级文案的职位。</p></blockquote><p><strong>Chandler Bing:</strong> Me, that guy who just said butt cracks?</p><blockquote><p>我，那个刚刚说屁股裂的家伙？</p></blockquote><p><strong>Steve:</strong> Yes, that&#39;s right. We&#39;re excited about the level of sophistication you&#39;ll be bringing to the job.</p><blockquote><p>是的，没错。我们对您将在工作中带来的复杂程度感到兴奋。</p></blockquote><p><strong>Chandler Bing:</strong> Ok well, thanks, you won&#39;t regret it. I&#39;ll see you tomorrow (hangs up).</p><blockquote><p>好吧，谢谢，你不会后悔的。明天见（挂断电话）。</p></blockquote><p><em>(he idly goes to the sofa, starts browsing a magazine. Everybody stares at him)</em></p><blockquote><p><em>（他懒洋洋地走到沙发上，开始浏览杂志。每个人都盯着他看）</em></p></blockquote><p><strong>Chandler Bing:</strong> What? (pause) Oh, yeah, I&#39;m gonna be a junior copywriter.</p><blockquote><p>什么？（停顿）哦，是的，我会成为一名初级文案。</p></blockquote><p><strong>Everybody:</strong> (excited) Oh my God, congratulations!</p><blockquote><p>（激动地）哦，天哪，恭喜你！</p></blockquote><p><strong>Monica Geller:</strong> Oh sweetie, I&#39;m so proud of you!</p><blockquote><p>哦，亲爱的，我真为你骄傲！</p></blockquote><p><strong>Chandler Bing:</strong> Does that mean I get the good loving tonight?</p><blockquote><p>这是不是意味着今晚我得到了一份美好的爱情？</p></blockquote><p><strong>Monica Geller:</strong> You bet! No TV or anything! (she gets up from the sofa and goes to the kitchen area)</p><blockquote><p>当然！没有电视什么的！（她从沙发上站起来，走向厨房）</p></blockquote><p><strong>Joey Tribbiani:</strong> (to Chandler) Hey, that is so great about the job.</p><blockquote><p>（对钱德勒）嘿，这份工作太棒了。</p></blockquote><p><strong>Chandler Bing:</strong> Thanks, man.</p><blockquote><p>谢谢，伙计。</p></blockquote><p><strong>Joey Tribbiani:</strong> And I like to think I had a little something to do with it.</p><blockquote><p>我喜欢认为这和我有点关系。</p></blockquote><p><strong>Chandler Bing:</strong> Really? What?</p><blockquote><p>真的吗？什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Well, before, with the wishbone... I didn&#39;t wish we would win the lottery, I wished you&#39;d get the job.</p><blockquote><p>好吧，在之前，和许愿骨一起。。。我不希望我们中彩票，我希望你能得到这份工作。</p></blockquote><p><strong>Chandler Bing:</strong> (smiling, surprised) Oh yeah? (looks towards the kitchen, worried) Listen, don&#39;t tell Monica, she&#39;ll rip your heart right out.</p><blockquote><p>（微笑，惊讶）哦，是吗？（焦急地看着厨房）听着，别告诉莫妮卡，她会把你的心撕碎的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh yeah.</p><blockquote><p>哦，是的。</p></blockquote><p><strong>Rachel Green:</strong> You know what? There is a little part of me that really thought we were gonna win.</p><blockquote><p>你知道吗？我有一点真的认为我们会赢。</p></blockquote><p><strong>Ross Geller:</strong> Me too. So much for my dinosaur/Amelia Earhart theme park.</p><blockquote><p>我也是。我的恐龙/阿米莉亚·埃尔哈特主题公园到此为止。</p></blockquote><p><strong>Phoebe Buffay:</strong> You guys, what was the Powerball number again?</p><blockquote><p>你们这些家伙，力量球的号码又是多少？</p></blockquote><p>Monica and **Ross Geller: **Seven.</p><blockquote><p>莫妮卡和<strong>罗斯·盖勒：</strong>七。</p></blockquote><p><strong>Phoebe Buffay:</strong> We won.</p><blockquote><p>我们赢了。</p></blockquote><p><strong>Rachel Green:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> We won!</p><blockquote><p>我们赢了！</p></blockquote><p><strong>Monica Geller:</strong> Let me see!</p><blockquote><p>让我想想！</p></blockquote><p><em>(they all jump up excitedly and try to see the ticket)</em></p><blockquote><p><em>（他们都兴奋地跳起来，想看看票）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Don&#39;t tear it.</p><blockquote><p>别扯了。</p></blockquote><p><strong>Ross Geller:</strong> Phoebe, you don&#39;t have any of the first five numbers.</p><blockquote><p>菲比，前五个数字你都没有。</p></blockquote><p><strong>Phoebe Buffay:</strong> I know that, but look, we&#39;ve got the Powerball number, we&#39;ve won 3 dollars!</p><blockquote><p>我知道，但是看，我们有强力球号码，我们赢了3美元！</p></blockquote><p><strong>Chandler Bing:</strong> Wow, you&#39;d think we should get that over 20 years or go for the big payout.</p><blockquote><p>哇，你会认为我们应该在20年内得到它，否则就要花大价钱了。</p></blockquote><p><strong>Phoebe Buffay:</strong> (still very excited) I don&#39;t care, I&#39;ve never won anything before, I can&#39;t believe this!</p><blockquote><p>（仍然很兴奋）我不在乎，我从来没有赢过任何东西，我真不敢相信！</p></blockquote><p><strong>Rachel Green:</strong> So Pheebs, what are you going to do with your $3?</p><blockquote><p>菲比，你打算用你的3美元做什么？</p></blockquote><p><strong>Phoebe Buffay:</strong> It&#39;s not all mine. We all get 50 cents.</p><blockquote><p>这不全是我的。我们都得到50美分。</p></blockquote><p><strong>Monica Geller:</strong> You know what? You can have mine.</p><blockquote><p>你知道吗？你可以拿我的。</p></blockquote><p><strong>Chandler Bing:</strong> Me too.</p><blockquote><p>我也是。</p></blockquote><p><strong>Joey Tribbiani:</strong> Me too.</p><blockquote><p>我也是。</p></blockquote><p><strong>Rachel Green:</strong> Me too.</p><blockquote><p>我也是。</p></blockquote><p><em>(they all look at Ross)</em></p><blockquote><p><em>（他们都看着罗斯）</em></p></blockquote><p><strong>Ross Geller:</strong> I guess if everybody else is...</p><blockquote><p>我想如果其他人都是。。。</p></blockquote><p>Closing credits</p><blockquote><p>期末学分</p></blockquote><hr><p>🎬 <em>Central Perk. They&#39;re all sitting there as usual, except Joey. Gunther is serving a nearby table.</em></p><blockquote><p>🎬 <em>中央公园。他们都像往常一样坐在那里，除了乔伊。冈瑟在附近的桌子上招待客人。</em></p></blockquote><p><em>(Joey comes in from the back of the coffee house)</em></p><blockquote><p><em>（乔伊从咖啡馆后面进来）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (sitting in a chair) Hey guys, so I just called the Powerball hotline, can you believe it? Nobody won.</p><blockquote><p>（坐在椅子上）嘿，伙计们，我刚打了强力球热线，你们能相信吗？没有人赢。</p></blockquote><p><strong>Phoebe Buffay:</strong> I beg to differ (shows him her cup of coffee and her plate of cookies).</p><blockquote><p>我不同意（给他看她那杯咖啡和那盘饼干）。</p></blockquote><p><strong>Gunther:</strong> Maybe nobody won the jackpot, but there was this guy in here earlier, and he found the ticket on the street, right outside, and won $10,000 (goes to the counter).</p><blockquote><p>也许没人中头奖，但早些时候这里有个家伙，他在街上找到了彩票，就在外面，赢了10000美元（去柜台）。</p></blockquote><p><em>(They all glare evilly at Phoebe)</em></p><blockquote><p><em>（他们都恶狠狠地瞪着菲比）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> (hides her mouth behind the cup and speaks in the &quot;pigeon voice&quot; from before) Coo, again. Don&#39;t blame the pretty lady. It was not her fault. It was me, the pigeon, coo! (pause) Seriously, stop staring at her.</p><blockquote><p>（把嘴藏在杯子后面，用前面的“鸽子声”说话）咕，又来了。别怪那位漂亮的女士。这不是她的错。是我，鸽子，咕！（停顿）说真的，别盯着她看。</p></blockquote><p><em>(Joey stares around dumbly looking for the &quot;talking pigeon&quot;)</em></p><blockquote><p><em>（乔伊目不转睛地四处寻找“会说话的鸽子”）</em></p></blockquote>`,644)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};